      var pm = tm[4].toLowerCase() === 'p';
      if (pm && h < 12) h += 12;
      if (!pm && h === 12) h = 0;
    }
    if (h > 23 || mi > 59 || sec > 59) return null;
    s = s.replace(tm[0], ' ');
