  s = s.replace(/,/g, ' ').replace(/\s+/g, ' ').trim();

  var y, mo, d, m, a, b, yr = function (t) { t = +t; return t < 100 ? t + (t < 70 ? 2000 : 1900) : t; };
  if ((m = s.match(/^(\d{4})[-\/.](\d{1,2})[-\/.](\d{1,2})$/))) {          // 2021-03-04
