  } else if ((m = s.match(/^(\d{1,2})[-\/.](\d{1,2})[-\/.](\d{2}|\d{4})$/))) { // 3/4/21, 04-03-2021
    a = +m[1]; b = +m[2]; y = yr(m[3]);
