    d = +m[1]; mo = MON[m[2].slice(0, 3).toLowerCase()]; y = yr(m[3]);
  } else if ((m = s.match(/^([a-z]{3,9})\.?[\s\-\/.]*(\d{1,2})[\s\-\/.]+(\d{2}|\d{4})$/i))) { // Mar 3 2021
    mo = MON[m[1].slice(0, 3).toLowerCase()]; d = +m[2]; y = yr(m[3]);
